def per_chain():
    out = []
    for cid in ALL:
        o = c[str(cid)]; by = {}
        for r in o['rows']: by.setdefault(r['cls'], []).append(r)
        parts = []
        for k, rs in sorted(by.items(), key=lambda kv: -len(kv[1])):
            rs.sort(key=lambda r: -abs(r['balHuman']))
            names = ', '.join(dict.fromkeys((r['symbol'] or r['token'][:10]) for r in rs[:4]))
            parts.append('%d %s (%s)' % (len(rs), k, names))
        res = '; '.join(parts) if parts else 'none'
        out.append('%s (%d): %s tokens tested; list built from %s. Blocks %s to %s, %s seconds. Tokens that do not reconcile: %s.' % (o['name'], cid, format(o['universe'], ','), SRC[cid], format(o['B1'], ','), format(o['B2'], ','), format(o['seconds'], ','), res))
    return ' '.join(out)
